const promoteNextReserve = `-- name: PromoteNextReserve :one
UPDATE final_winners
SET status = 'notified', promoted_at = now(), deadline = $1
WHERE id = (
    SELECT fw.id FROM final_winners fw
    WHERE fw.final_draw_id = $2 AND fw.is_reserve AND fw.status = 'selected' AND fw.promoted_at IS NULL
    ORDER BY fw.reserve_position
    FOR UPDATE SKIP LOCKED
    LIMIT 1
)
RETURNING id, final_draw_id, user_id, tickets_count, is_reserve, status, deadline, contact_name, consent_given_at, created_at, reserve_position, dialog_step, forfeit_reason, promoted_at, contact_purged_at
`

type PromoteNextReserveParams struct {
	NewDeadline pgtype.Timestamptz
	DrawID      int64
}

// Moves the first reserve in the queue to an active winner with a fresh deadline.
func (q *Queries) PromoteNextReserve(ctx context.Context, arg PromoteNextReserveParams) (FinalWinner, error) {
	row := q.db.QueryRow(ctx, promoteNextReserve, arg.NewDeadline, arg.DrawID)
	var i FinalWinner
	err := row.Scan(
		&i.ID,
		&i.FinalDrawID,
		&i.UserID,
		&i.TicketsCount,
		&i.IsReserve,
		&i.Status,
		&i.Deadline,
		&i.ContactName,
		&i.ConsentGivenAt,
		&i.CreatedAt,
		&i.ReservePosition,
		&i.DialogStep,
		&i.ForfeitReason,
		&i.PromotedAt,
		&i.ContactPurgedAt,
	)
	return i, err
}

const purgeFinalContacts = `-- name: PurgeFinalContacts :execrows
UPDATE final_winners
SET contact_name = NULL, contact_purged_at = now(),
    dialog_step = CASE WHEN dialog_step = 'consent' THEN NULL ELSE dialog_step END
WHERE contact_name IS NOT NULL
`

// Removes collected names. Consent records stay as evidence; a dialog waiting
// for the consent of a purged name is reset.
func (q *Queries) PurgeFinalContacts(ctx context.Context) (int64, error) {
	result, err := q.db.Exec(ctx, purgeFinalContacts)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

